// lambda-function/lambda-handler.ts
import { APIGatewayProxyEvent, APIGatewayProxyResult } from 'aws-lambda';
import * as client from 'dynamodb-doc';

const ddb = new client.DynamoDB({
    region: process.env.AWS_REGION,
    retries: 5,
});

const table = ddb.table(process.env.DYNAMODB_TABLE);

const USER_TABLE = 'users';

interface UserInfo {
    userId: string;
    name: string;
    email: string;
    createdAt: string;
    updatedAt: string;
    data: string  // Encrypted payload
}

async function getUser(userId: string): Promise<UserInfo> {
    const response = await table.get({
        Key: { userId },
        ConsistentRead: true,
    }).promise();

    return response.Item;
}

async function createUser(userInfo: UserInfo): Promise<UserInfo> {
    const newUserInfo = {
        ...userInfo,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        userId: Date.now().toString(),
    };

    await table.put({
        Item: newUserInfo,
    }).promise();

    return newUserInfo;
}

async function updateUser(userId: string, updates: Partial<UserInfo>): Promise<UserInfo> {
    const currentUserInfo = await getUser(userId);
    const updatedInfo = {
        ...currentUserInfo,
        ...updates,
        updatedAt: new Date().toISOString(),
    };

    await table.put({
        Item: updatedInfo,
    }).promise();

    return updatedInfo;
}

