I'll help you create a Java program for converting lowercase letters to uppercase. Here's a well-structured solution that follows proper conventions:

```java
import java.util.Scanner;

/**
 * Main class for lowercase to uppercase conversion utility
 */
public class StringConverter {

    /**
     * Main method to run the program
     * @param args command line arguments (not used in this program)
     */
    public static void main(String[] args) {
        // Initialize scanner for user input
        Scanner scanner = null;
        String userInput = null;

        try {
            scanner = new Scanner(System.in);

            // Display welcome message and instructions
            System.out.println("=== String Case Converter ===");
            System.out.println("This program converts lowercase letters to uppercase.");
            System.out.println("Please enter a string:");

            // Get user input
            userInput = scanner.nextLine();

            // Validate and process input
            if (processInput(userInput)) {
                System.out.println("\nConversion complete!");
            }

        } catch (Exception e) {
            // Handle any unexpected errors
            System.out.println("An unexpected error occurred: " + e.getMessage());
        } finally {
            // Properly close resources
            if (scanner != null) {
                scanner.close();
            }
        }
    }

    /**
     * Processes the user input string and performs the conversion
     * @param input the original string to convert
     * @return true if conversion was successful, false otherwise
     */
    public static boolean processInput(String input) {
        // Check for null or empty input
        if (input == null || input.isEmpty()) {
            System.out.println("Error: Input cannot be null or empty.");
            System.out.println("Please try again with a valid string.");
            return false;
        }

        // Conversion and validation
        String convertedString = convertToUppercase(input);
        validateAndDisplayResult(convertedString);
        return true;
    }

    /**
     * Converts lowercase characters to uppercase
     * @param input the string to convert
     * @return the converted string
     */
    private static String convertToUppercase(String input) {
        return input.toUpperCase();
    }

    /**
     * Validates the converted string and displays results
     * @param input the string to validate and display
     */
    private static void validateAndDisplayResult(String input) {
        // Check for invalid characters
        if (containsInvalidCharacters(input)) {
            System.out.println("Error: String contains non-alphabetic characters.");
            System.out.println("Please use only alphabetic characters with valid input.");
        } else {
            System.out.println("Converted string: " + input);
        }
    }

    /**
     * Checks if the input contains only alphabetic characters
     * @param input the string to check
     * @return true if string contains only alphabetic characters, false otherwise
     */
    private static boolean containsInvalidCharacters(String input) {
        // Check if input contains only alphabetic characters
        for (char ch : input.toCharArray()) {
            if (!Character.isLetter(ch)) {
                return true; // Contains non-alphabetic character
            }
        }
        return false; // All characters are alphabetic
    }
}
